CREATE TABLE public.a2p_agency_profile (id text PRIMARY KEY DEFAULT 'est8', ciphertext text NOT NULL, verified_at timestamptz, verified_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.a2p_agency_profile TO service_role;
ALTER TABLE public.a2p_agency_profile ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.a2p_agency_members (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), authorized boolean NOT NULL DEFAULT false, authorized_by uuid NOT NULL, reason text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.a2p_agency_members TO authenticated;
GRANT ALL ON public.a2p_agency_members TO service_role;
ALTER TABLE public.a2p_agency_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY agency_member_read ON public.a2p_agency_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.a2p_capability_cache(id text PRIMARY KEY DEFAULT 'telnyx', allowed boolean NOT NULL DEFAULT false, blocker text, enums jsonb NOT NULL DEFAULT '{}', checked_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.a2p_capability_cache TO authenticated;
GRANT ALL ON public.a2p_capability_cache TO service_role;
ALTER TABLE public.a2p_capability_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY capability_read ON public.a2p_capability_cache FOR SELECT TO authenticated USING(true);
CREATE TABLE public.sms_consent_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), phone_number text NOT NULL, transactional boolean NOT NULL DEFAULT false, marketing boolean NOT NULL DEFAULT false, source text NOT NULL, disclosure_version text NOT NULL, disclosure text NOT NULL, request_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.sms_consent_events TO authenticated;
GRANT ALL ON public.sms_consent_events TO service_role;
ALTER TABLE public.sms_consent_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY consent_read ON public.sms_consent_events FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.sms_suppressions(user_id uuid NOT NULL REFERENCES public.profiles(id), phone_number text NOT NULL, suppressed boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,phone_number));
GRANT SELECT ON public.sms_suppressions TO authenticated;
GRANT ALL ON public.sms_suppressions TO service_role;
ALTER TABLE public.sms_suppressions ENABLE ROW LEVEL SECURITY;
CREATE POLICY suppression_read ON public.sms_suppressions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.a2p_correction_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), request text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.a2p_correction_requests TO authenticated;
GRANT ALL ON public.a2p_correction_requests TO service_role;
ALTER TABLE public.a2p_correction_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY correction_read ON public.a2p_correction_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
ALTER TABLE public.a2p_registrations ADD COLUMN agency_registration_id uuid REFERENCES public.a2p_registrations(id);
CREATE TABLE public.a2p_public_form_verification(id text PRIMARY KEY DEFAULT 'est8', verified_at timestamptz, verified_by uuid, disclosure_version text NOT NULL DEFAULT '2026-11-v1', source text, profile_updated_at timestamptz);
GRANT SELECT ON public.a2p_public_form_verification TO authenticated;
GRANT ALL ON public.a2p_public_form_verification TO service_role;
ALTER TABLE public.a2p_public_form_verification ENABLE ROW LEVEL SECURITY;
CREATE POLICY form_verification_read ON public.a2p_public_form_verification FOR SELECT TO authenticated USING(true);